import React from 'react';
import { useNavigate } from 'react-router-dom';
import { logout } from '../services/api'; // Make sure the path is correct

const UserDashboard = () => {
  const navigate = useNavigate();

  const handleLogout = async () => {
    try {
      // Call the logout function from api.js and pass navigate for redirection
      await logout(navigate); // logout will handle the token removal and redirection

      // Optional: remove the token from localStorage manually (for completeness)
      localStorage.removeItem('token');
    } catch (error) {
      console.error('Logout failed:', error);
      alert('There was an error logging out. Please try again.');
    }
  };

  return (
    <div>
      <h1>User Dashboard</h1>
      <button onClick={() => navigate('/exam-data-user')}>Manage Exam Data</button>
      
      {/* Logout button */}
      <button onClick={handleLogout}>Logout</button>
    </div>
  );
};

export default UserDashboard;
